package io.finstream.anomaly;
import static org.assertj.core.api.Assertions.assertThat; import io.finstream.config.FinStreamProperties; import io.finstream.domain.*; import java.math.BigDecimal; import java.time.*; import java.util.List; import org.junit.jupiter.api.*;
class AnomalyRulesTest { FinStreamProperties props=new FinStreamProperties(new FinStreamProperties.Market(List.of("BTCUSDT"),new FinStreamProperties.Binance(false,null)),new FinStreamProperties.Anomaly(Duration.ofMinutes(5),new FinStreamProperties.Rule(true,Duration.ofMinutes(5),3),new FinStreamProperties.Rule(true,Duration.ofMinutes(5),3),new FinStreamProperties.VolumeRule(true,3))); MarketEvent event=new MarketEvent("TEST","BTCUSDT",MarketEvent.EventType.TRADE,Instant.EPOCH,Instant.EPOCH,BigDecimal.TEN,BigDecimal.ONE); MarketState state(double ret,double ratio){return new MarketState("BTCUSDT",Instant.EPOCH,BigDecimal.TEN,0,ret,0,1,2,BigDecimal.TEN,BigDecimal.ONE,ratio);} @Test void rapidDropTriggers(){assertThat(new RapidDropRule(props).evaluate(event,state(-3.1,0))).isPresent();} @Test void rapidPumpTriggers(){assertThat(new RapidPumpRule(props).evaluate(event,state(3.1,0))).isPresent();} @Test void abnormalVolumeTriggers(){assertThat(new AbnormalVolumeRule(props).evaluate(event,state(0,3.1))).isPresent();} @Test void rulesDoNotTriggerBelowThreshold(){assertThat(new RapidDropRule(props).evaluate(event,state(-2.9,2))).isEmpty(); assertThat(new RapidPumpRule(props).evaluate(event,state(2.9,2))).isEmpty(); assertThat(new AbnormalVolumeRule(props).evaluate(event,state(0,2.9))).isEmpty();}}
